- Namespace: Player
- class Player { public:
  - explicit Player(const Time::IClock& clock);
  - void set_current_media(const Media::MediaMetadata* media);
  - const Media::MediaMetadata* current_media() const;
  - PlaybackState state() const noexcept;
  - std::int64_t position_ms() const noexcept;
  - std::int64_t duration_ms() const noexcept;
  - bool play();
  - void pause() noexcept;
